begin;
set local search_path=public,extensions;
select no_plan();
select is(private.normalize_client_phone('(11) 99999-4321'),'+5511999994321','E.164 brasileiro com DDD');
select is(private.normalize_client_phone('+351 912 345 678'),'+351912345678','Preserva país explícito');
select is(private.normalize_client_phone('99999-4321'),null,'Não inventa DDD');
select is(private.normalize_client_phone('abc11999994321'),null,'Não remove letras silenciosamente');
select is(private.normalize_client_phone(null),null,'Telefone opcional');
select ok(not has_table_privilege('authenticated','private.clients','SELECT'),'Sem leitura direta de dados privados');
select ok(not has_table_privilege('service_role','private.client_links','UPDATE'),'Serviço sem mutação direta dos vínculos');
select ok(not has_function_privilege('anon','public.save_client(uuid,uuid,text,text,text,uuid,integer,boolean)','EXECUTE'),'Anônimo sem escrita RPC');
select ok(not has_function_privilege('service_role','public.merge_clients(uuid,uuid,uuid,uuid,integer,integer,text,boolean)','EXECUTE'),'Service role não executa merge de usuário');
select ok((select bool_and(proconfig @> array['search_path=""']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and proname in('search_clients','save_client','merge_clients','set_client_link','client_detail','preview_client_import')),'RPCs com search_path vazio');
select set_config('request.jwt.claims',json_build_object('sub',(select id from auth.users where email='a@example.com'),'role','authenticated')::text,true);
create temp table client_fixture(k text,id uuid);
grant all on client_fixture to authenticated;
set local role authenticated;
insert into client_fixture values('source',public.save_client('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Pessoa SQL sintética'));
insert into client_fixture values('dest',public.save_client('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Outra pessoa SQL sintética'));
select throws_ok($$select public.save_client('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Pessoa SQL sintética')$$,'22023',null,'Homônimo exige revisão');
select throws_ok($$select public.save_client('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000012','Proibido')$$,'42501',null,'Unidade não atribuída negada');
select throws_ok($$select public.merge_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from client_fixture where k='source'),(select id from client_fixture where k='dest'),1,1,'Revisão sintética',false)$$,'22023',null,'Merge exige confirmação');
reset role;
select throws_ok($$insert into private.clients(tenant_id,unit_id,name) values('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Cruzado')$$,'23503',null,'FK composta impede unidade de outra clínica');
select throws_ok($$insert into private.clients(tenant_id,unit_id,name,state,merged_into) values('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011','Cruzado','archived',(select id from client_fixture where k='source'))$$,'23503',null,'Sobrevivente deve pertencer ao tenant/unidade');
select throws_ok($$update private.clients set merged_into=id,state='archived' where id=(select id from client_fixture where k='source')$$,'23514',null,'Autorreferência recusada');
select throws_ok($$insert into private.client_links(tenant_id,unit_id,client_id,integration_id,kind,external_ref,state,source_ref,updated_by) values('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011',(select id from client_fixture where k='source'),gen_random_uuid(),'card','teste','pending_review','teste',gen_random_uuid())$$,'23503',null,'Vínculo não cruza tenant');
select throws_ok($$insert into private.client_events(tenant_id,unit_id,client_id,actor_id,action) values('20000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000011',(select id from client_fixture where k='source'),gen_random_uuid(),'teste')$$,'23503',null,'Evento não cruza tenant');
set local role authenticated;
select public.set_client_link('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from client_fixture where k='source'),'contact','rollback_sql','origem_sql');
reset role;
-- Falha depois da movimentação comprova rollback transacional de todos os efeitos.
create function pg_temp.fail_merge() returns trigger language plpgsql as $$ begin if new.action='client_merged' then raise exception 'Falha injetada' using errcode='P0001'; end if; return new; end $$;
create trigger test_merge_rollback before insert on private.client_events for each row execute function pg_temp.fail_merge();
set local role authenticated;
select throws_ok($$select public.merge_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from client_fixture where k='source'),(select id from client_fixture where k='dest'),2,1,'Revisão sintética',true)$$,'P0001','Falha injetada','Falha ao gravar evento aborta merge');
reset role;
select is((select state from private.clients where id=(select id from client_fixture where k='source')),'active','Origem permanece ativa após rollback');
select is((select version from private.clients where id=(select id from client_fixture where k='dest')),1,'Versão do sobrevivente preservada após rollback');
select is((select client_id from private.client_links where external_ref='rollback_sql'),(select id from client_fixture where k='source'),'Vínculo retorna à origem após falha ao gravar evento');
drop trigger test_merge_rollback on private.client_events;
-- Matriz por papel sem depender da UI.
update public.tenant_memberships set role='reception' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='a@example.com');
set local role authenticated;
select lives_ok($$select public.search_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'Recepção lê clientes');
select throws_ok($$select public.merge_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011',(select id from client_fixture where k='source'),(select id from client_fixture where k='dest'),2,1,'Revisão sintética',true)$$,'42501',null,'Recepção não faz merge');
reset role;
update public.tenant_memberships set role='professional' where tenant_id='10000000-0000-0000-0000-000000000001' and user_id=(select id from auth.users where email='a@example.com');
set local role authenticated;
select lives_ok($$select public.search_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'Profissional lê na unidade atribuída');
select throws_ok($$select public.save_client('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Proibido')$$,'42501',null,'Profissional não altera cadastro');
reset role;
insert into private.clients(tenant_id,unit_id,name) select '10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Paginação SQL '||n from generate_series(1,51) n;
set local role authenticated;
select is(jsonb_array_length(public.search_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Paginação SQL')),50,'Pesquisa limitada a 50');
select is(jsonb_array_length(public.search_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Paginação SQL',(public.search_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011','Paginação SQL')->49->>'id')::uuid)),1,'Cursor avança sem repetir registros');
reset role;
update public.tenant_entitlements set enabled=false where tenant_id='10000000-0000-0000-0000-000000000001' and module_key='core';
set local role authenticated;
select throws_ok($$select public.search_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'42501',null,'Core desabilitado bloqueia clientes');
reset role;
update public.tenant_entitlements set enabled=true where tenant_id='10000000-0000-0000-0000-000000000001' and module_key='core';
update public.tenants set status='suspended' where id='10000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select public.search_clients('10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000011')$$,'42501',null,'Suspensão bloqueia leitura imediatamente');
reset role;
select * from finish();
rollback;
